'use strict';
// A quieter study interface, with verification scoped to the visible card.
let workView='exercise',briefOpen={},localFeedback=null,detailsOpen=false;
game.checks||={};game.sound=false;game.music=false;
screen=game.started?'mission':'map';
const originalModelHTML=modelHTML,originalRulesHTML=rulesHTML;
const stepsShort=['Entità','Attributi','Associazioni','Relazioni','Prova'];
const purposes=['Riconosci le entità','Seleziona attributi e chiavi','Associa le entità','Costruisci le relazioni','Metti alla prova il modello'];
const briefs=['Seleziona tutti i tipi di oggetti descritti dalla traccia. Puoi scegliere più risposte.','Seleziona gli attributi, poi premi PK accanto a quelli che formano la chiave.','Individua le associazioni, poi completa le due regole di lettura.','Scegli le relazioni e aggiungi le colonne con chiavi e vincoli.','Usa lo schema per ragionare sui casi proposti.'];
function currentItem(c,s){const list=V3Session.items(c,s);const i=Math.min(pageByStep[s.step]||0,Math.max(0,list.length-1));pageByStep[s.step]=i;return {list,i,item:list[i]};}
function checked(s,id){const recorded=game.checks[current]?.[s.step]?.[id];return s.passed.includes(s.step)||(typeof recorded==='string'&&recorded===V3Session.signature(s,id));}
function markChecked(s,id){game.checks[current]||={};game.checks[current][s.step]||={};game.checks[current][s.step][id]=V3Session.signature(s,id);}
function award(s){const r=runFor(),key='step-'+s.step;if(r.rewarded.includes(key))return 0;r.rewarded.push(key);r.points+=100;return 100;}
function clearLocal(){localFeedback=null;feedback=null;detailsOpen=false;}
function focusCard(){const n=document.getElementById('card-heading');n?.focus({preventScroll:true});n?.scrollIntoView({block:'start',behavior:'instant'});}
function shellHeader(){return `<header class="v3-header"><a class="v3-brand" href="../" aria-label="Officina E/R: cambia versione o studente">${icon('link',23)}<strong>officina <span>E/R</span></strong></a><nav aria-label="Navigazione principale">${[['map','Esercizi'],['mission','Incarico'],['rules','Ripasso'],['log','Progressi']].map(([id,label])=>`<button data-v3="nav" data-screen="${id}" ${screen===id||id==='mission'&&['boss','complete'].includes(screen)?'aria-current="page"':''}>${label}</button>`).join('')}</nav></header>`;}
function stepper(s){return `<nav class="v3-steps" aria-label="Fasi dell’incarico">${stepsShort.map((n,i)=>`<button data-action="step" data-step="${i}" ${i>s.passed.length?'disabled':''} ${i===s.step?'aria-current="step"':''} aria-label="${i+1}. ${n}${s.passed.includes(i)?', verificato':''}"><b>${s.passed.includes(i)?'✓':i+1}</b><span>${n}</span></button>`).join('')}</nav>`;}
function promptHTML(c,s){const open=briefOpen[current]??(s.step===0);return `<details class="brief v3-brief" id="task-brief" ${open?'open':''}><summary>Traccia <span>${open?'Riduci':'Leggi'}</span></summary><p class="brief-body">${esc(c.prompt)}</p></details>`;}
function selectorHTML(c,s){const {list,i}=currentItem(c,s);if(list.length<2)return '';return `<div class="v3-card-tabs" role="group" aria-label="Schede di ${stepsShort[s.step]}">${list.map((it,j)=>`<button data-v3="page" data-page="${j}" aria-pressed="${j===i}"><span>${esc(it.name)}</span><small>${checked(s,it.id)?'✓ Verificata':'Da verificare'}</small></button>`).join('')}</div>`;}
stageHTML=function(c,s){const temp=document.createElement('div');temp.innerHTML=baseStageHTML(c,s);const {list,i}=currentItem(c,s);if(list.length){const selector={1:'.entity-editor',2:'.relation-editor',3:'.table-editor',4:'.question'}[s.step];[...temp.querySelectorAll(selector)].forEach((b,j)=>{if(i!==j)b.remove();});}temp.querySelectorAll('.tag').forEach(n=>{if(n.textContent==='Entità')n.remove();});temp.querySelectorAll('.selection-foot span:nth-child(2)').forEach(n=>n.remove());temp.querySelectorAll('.entity-editor,.relation-editor,.table-editor,.question').forEach(n=>n.setAttribute('aria-label','Scheda attiva'));return selectorHTML(c,s)+temp.innerHTML;};
modelHTML=function(c,s){const t=document.createElement('div');t.innerHTML=originalModelHTML(c,s);t.querySelector('.model-top small')?.remove();t.querySelector('.rule-note')?.remove();t.querySelector('.diagram-note')?.remove();const legend=t.querySelector('.legend');if(legend){const text=modelMode==='tables'?'PK identifica la riga. FK riferisce una chiave di un’altra relazione. UNIQUE impedisce ripetizioni.':s.step<2?'PK indica gli attributi della chiave, anche la parte locale di un identificatore composto.':'Linea continua: obbligatoria. Tratteggiata: facoltativa. Vuota: da scegliere. 1 / N agli estremi; ▼ / ▲ indica il verso di lettura.';legend.outerHTML=`<details class="v3-legend"><summary>Legenda</summary><p>${text}</p></details>`;}return t.innerHTML;};
function feedbackV3(){const f=localFeedback||feedback;if(!f)return '';return `<section class="feedback ${f.ok?'success':''}" id="feedback" tabindex="-1" role="status"><h3>${f.ok?'✓ Verifica superata':'Da rivedere'}</h3>${f.ok?`<p>${esc(f.message||'Puoi continuare.')}</p>`:`<ul>${f.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}${f.targets?.length?`<div class="correction-links">${f.targets.map(t=>`<button data-v3="page" data-page="${t.index}">Rivedi ${esc(t.name)}</button>`).join('')}</div>`:''}</section>`;}
function playV3(c,s){const {list,i,item}=currentItem(c,s);return `<header class="v3-mission"><p class="eyebrow">INCARICO ${cases.indexOf(c)+1} DI ${cases.length}</p><h1>${missionNames[cases.indexOf(c)]}</h1></header>${stepper(s)}<div class="mobile-work-tabs" role="group" aria-label="Vista dell’incarico"><button data-v3="work-view" data-view="exercise" aria-pressed="${workView==='exercise'}">Esercizio</button><button data-v3="work-view" data-view="model" aria-pressed="${workView==='model'}">Schema</button></div><div class="v3-work" data-work-view="${workView}"><section class="exercise-pane"><header class="v3-command"><div class="command-line"><h2 id="card-heading" tabindex="-1">${purposes[s.step]}</h2><span>${s.step+1}/5${list.length>1?' · '+(i+1)+'/'+list.length:''}</span></div><p>${briefs[s.step]}</p></header>${promptHTML(c,s)}${stageHTML(c,s)}${feedbackV3()}<div class="help-row"><button class="text-button" data-action="hint">${icon('bulb',18)}${s.hints[s.step]?'Un altro indizio':'Un indizio'}</button>${s.hints[s.step]>=2?`<button class="text-button" data-v3="solve-card">${item?'Soluzione di '+esc(item.name):'Soluzione del passaggio'}</button>`:''}</div>${s.hints[s.step]?`<aside class="v3-hint" role="status"><img src="../v2/assets/archi.webp" alt="" width="34" height="40"><div><strong>Archi · un suggerimento</strong><p>${esc(hintFor(c,s))}</p></div></aside>`:''}${s.assisted.includes(s.step)?'<p class="small-note">Soluzione consultata. Puoi riprovare l’incarico dopo averlo completato.</p>':''}</section><aside class="model-pane" aria-label="Il tuo schema">${modelHTML(c,s)}</aside></div>`;}
function footerV3(c,s){const {list,i,item}=currentItem(c,s);const good=item&&checked(s,item.id);const passed=s.passed.includes(s.step);let action='verify',label='Verifica '+(item?item.name.toLowerCase():s.step===2?'associazioni':'le scelte');if(passed){action='advance';label=s.step===4?'Ultimo controllo':'Continua: '+stepsShort[s.step+1];}else if(good&&i<list.length-1){action='next-card';label='Continua: '+list[i+1].name;}else if(good){action='verify-stage';label='Verifica il passaggio';}return `<footer class="v3-footer"><div><button class="back" data-v3="${workView==='model'?'return-exercise':'back'}" ${workView!=='model'&&s.step===0&&i===0?'disabled':''}>← Indietro</button><button class="primary" data-v3="${workView==='model'?'return-exercise':action}">${workView==='model'?'Torna all’esercizio':esc(label)}</button></div></footer>`;}
function hasWork(s){return s.entities.length||s.passed.length||Object.keys(s.tables).length||Object.keys(s.quiz).length;}
function mapV3(){return `<header class="v3-home"><span class="eyebrow">LABORATORIO DI BASI DI DATI</span><h1>Dalla traccia al modello.</h1><p>Sei esercizi per ripassare E/R e relazioni.<br>Scegli un incarico e riprendi da dove eri rimasto.</p></header><div class="v3-course-grid">${cases.map((c,i)=>{const s=states[c.id];return `<article class="v3-course"><div class="course-meta"><span>0${i+1}</span><span>≈ ${c.minutes} min</span></div><h2>${missionNames[i]}</h2><p>${['Libri e categorie in un catalogo.','Soci e tessere di un circolo.','Artisti, brani e partecipazioni.','Ordini e relative righe.','Ricette e sottopreparazioni.','Riviste, articoli, autori e argomenti.'][i]}</p><div class="course-bars" aria-label="${s.passed.length} di 5 passaggi verificati">${stepsShort.map((_,j)=>`<i class="${s.passed.includes(j)?'filled':''}"></i>`).join('')}</div><div class="course-bottom"><span>${s.completed?'Completato':s.passed.length?s.passed.length+'/5 verificati':hasWork(s)?'In corso':'Da iniziare'}</span><button class="secondary" data-action="case" data-id="${c.id}">${s.completed?'Rivedi':hasWork(s)?'Riprendi':'Inizia'} →</button></div></article>`;}).join('')}</div><p class="local-note">Salvataggio automatico in questo browser. <a href="../">Cambia versione o studente</a>.</p>`;}
rulesHTML=function(){return originalRulesHTML().replace('Prima scegli la cardinalità: 1:1, 1:N, N:1 oppure N:N, nell’ordine delle entità. Poi scegli separatamente se ciascuna entità partecipa in modo obbligatorio o facoltativo.','Leggi l’associazione nei due versi: «Ogni A deve / può … un solo / uno o più B». Deve e può definiscono la partecipazione; il numero massimo determina la cardinalità.');};
report=function(){return {app:'Officina E/R · Ripasso E/R',version:3,student:window.OfficinaProfile?.snapshot(window.OFFICINA_STUDENT)||null,theme:window.OFFICINA_THEME,exportedAt:new Date().toISOString(),xp:totalXP(),best:Object.fromEntries(Object.entries(game.best).map(([id,b])=>[id,{points:b.points}])),learning:states,events:game.log,note:'Dati locali modificabili. Nessuna certificazione di valutazione.'};};
function reportHTML(){return `<!doctype html><html lang="it"><meta charset="utf-8"><title>Officina E/R · Riepilogo</title><style>body{font:16px/1.6 system-ui;max-width:900px;margin:40px auto;padding:20px;color:#1c352e}table{border-collapse:collapse;width:100%}td,th{border:1px solid #cbd5c7;padding:10px;text-align:left}</style><h1>Officina E/R · Riepilogo del ripasso</h1><p><strong>${esc(window.OFFICINA_STUDENT?.name)}</strong> · ${esc(window.OFFICINA_STUDENT?.classe)}</p><p>${esc(new Date().toLocaleString('it-IT'))} · ${totalXP()} XP</p><table><tr><th>Incarico</th><th>Verifiche</th><th>Soluzione consultata</th></tr>${cases.map((c,i)=>`<tr><td>${missionNames[i]}</td><td>${states[c.id].passed.length}/5</td><td>${states[c.id].assisted.length?'Sì':'No'}</td></tr>`).join('')}</table><h2>Verifiche e aiuti</h2>${game.log.filter(e=>['verifica','verifica-scheda','verifica-associazioni','collaudo-guasto','indizio','soluzione'].includes(e.kind)).map(e=>`<p><strong>${esc(cases.find(c=>c.id===e.mission)?.short||e.mission)}</strong> · ${esc(e.item||'Passaggio '+e.step)} · ${esc(e.kind)}${typeof e.ok==='boolean'?' · '+(e.ok?'corretto':'da rivedere'):''}<br><small>${esc(e.at)}</small>${e.issues?.length?'<br>'+e.issues.map(esc).join('<br>'):''}</p>`).join('')}<p>Dati locali modificabili, non una certificazione di valutazione. Gli aiuti non riducono gli XP.</p></html>`;}
function progressV3(){return `<header class="view-title"><span class="eyebrow">IL TUO RIPASSO</span><h1>Progressi</h1><p>Conta ciò che hai verificato. Gli errori servono a capire dove tornare.</p></header><div class="v3-stats"><div><strong>${cases.filter(c=>states[c.id].completed).length}/6</strong><span>incarichi completati</span></div><div><strong>${totalXP()}</strong><span>XP · miglior risultato per incarico</span></div></div><p class="small-note">100 XP per ogni nuovo passaggio verificato nella V3. Nessuna penalità per errori o indizi. I punti precedenti restano conservati; ripetere lo stesso passaggio non aggiunge XP.</p><div class="progress-list">${cases.map((c,i)=>`<article><div><h2>${missionNames[i]}</h2><p>${states[c.id].passed.length}/5 passaggi · ${states[c.id].assisted.length?'soluzione consultata':'soluzione non consultata'}</p></div><button class="secondary" data-action="case" data-id="${c.id}">Apri</button></article>`).join('')}</div><div class="export-actions"><button class="secondary" data-game="download">Esporta risposte (JSON)</button><button class="secondary" data-v3="export-html">Riepilogo per il docente</button></div><p class="local-note">Dati locali e modificabili; nessun invio automatico. Le due versioni condividono i progressi di questo studente. Gli eventi importati dalle vecchie versioni restano senza nome.</p>`;}
function completeV3(c,s){return `<section class="v3-complete"><span class="eyebrow">INCARICO COMPLETATO</span><h1>${missionNames[cases.indexOf(c)]}</h1><p>Hai costruito il modello, verificato le scelte e corretto un errore nella conversione.</p><div class="rule-summary"><strong>Da ricordare</strong><p>${esc(c.rule)}</p></div><div class="export-actions"><button class="primary" data-v3="nav" data-screen="map">Scegli un altro incarico</button><button class="secondary" data-action="review">Rivedi il modello</button><button class="text-button" data-action="reset">Riprova da zero</button></div></section>`;}
const legacyBoss=bossHTML;
bossHTML=function(c){return legacyBoss(c).replace('C’è una scheda fuori posto.','Trova e correggi l’errore.').replace('Archi ha trovato un errore nel catalogo. Tocca una colonna e correggi il vincolo sbagliato.','Seleziona una colonna e correggi il vincolo che viola la traccia.').replace('Chiedi ad Archi','Un indizio');};
render=function(){const c=cases.find(c=>c.id===current),s=states[current];if(screen==='mission'&&s.completed&&!reviewing)screen=runFor().bossPassed?'complete':'boss';document.title=(screen==='mission'?missionNames[cases.indexOf(c)]:'Ripasso E/R')+' · Officina E/R';document.body.classList.remove('celebrating');document.getElementById('app').innerHTML=shellHeader()+(!storageOK?'<p class="storage-warning">Salvataggio non disponibile. Esporta le risposte prima di chiudere.</p>':'')+`<main class="v3-shell" id="workspace" tabindex="-1">${screen==='map'||screen==='start'?mapV3():screen==='rules'?rulesHTML():screen==='log'?progressV3():screen==='boss'?bossHTML(c):screen==='complete'?completeV3(c,s):playV3(c,s)}</main>`+(screen==='mission'?footerV3(c,s):screen==='boss'?'<footer class="v3-footer"><div><button class="back" data-v3="inspect">Rivedi il modello</button><button class="primary" data-game="boss-check">Verifica la correzione</button></div></footer>':'')+(dialog?dialogHTML():'');};
window.Game={beforeAction(a,c,s){recordActive();},afterAction(a,c,s,el){
 clearLocal();notice='';
 if(a==='case'){screen='mission';game.started=true;pageByStep={};workView='exercise';}
 if(['previous','step'].includes(a)){pageByStep={};workView='exercise';if(s.step<3)modelMode='er';}
 if(a==='hint'||a==='solve'){runFor().hints++;logEvent(a==='hint'?'indizio':'soluzione');}
 if(a==='solve'){for(const it of V3Session.items(c,s))delete game.checks[current]?.[s.step]?.[it.id];}
 if(a==='association-back')pageByStep={};
 if(a==='check-associations'&&!s.associationsConfirmed)localFeedback={ok:false,issues:['Rivedi le azioni presenti nella traccia: alcune mancano o non sono richieste.']};
 if(a==='check-associations'&&s.associationsConfirmed){pageByStep={};feedback=null;}
 if(a==='table'){pageByStep[3]=Math.max(0,Object.keys(s.tables).indexOf(el.dataset.name));}
 if(a==='review'){screen='mission';workView='model';}
 if(a==='confirm-reset'){game.runs[current]=GameCore.fresh();delete game.checks[current];pageByStep={};screen='mission';reviewing=false;workView='exercise';}
 logEvent('scelta',{action:a});persistGame();
}};
function finishStep(c,s){const result=ER.check(c,s,s.step);if(result.ok){if(!s.passed.includes(s.step))s.passed.push(s.step);const gain=award(s);localFeedback={ok:true,message:'Passaggio completato.'+(gain?' +'+gain+' XP.':'')};logEvent('verifica',{ok:true,step:s.step+1,gain});return true;}const list=V3Session.items(c,s),bad=list.map((it,index)=>({...it,index})).filter(it=>!V3Session.checkItem(c,s,it.id,ER).ok);if(s.step===3&&!bad.length){localFeedback={ok:true,message:'Questa relazione è corretta. Il modello è ancora incompleto: aggiungi le altre relazioni richieste dalla traccia.'};return false;}localFeedback={ok:false,issues:['Il passaggio non è ancora completo. Rivedi le schede indicate'+(s.step===3?' e verifica di avere creato tutte le relazioni necessarie.':'.')],targets:bad};return false;}
function actionV3(event){const el=event.target.closest('[data-v3]');if(!el)return;const a=el.dataset.v3,c=cases.find(c=>c.id===current),s=states[current],{list,i,item}=currentItem(c,s);let top=false,card=false;clearLocal();
 if(a==='nav'){screen=el.dataset.screen;workView='exercise';top=true;}
 if(a==='page'){pageByStep[s.step]=Number(el.dataset.page);card=true;}
 if(a==='work-view'){workView=el.dataset.view;top=true;}
 if(a==='return-exercise'){workView='exercise';card=true;}
 if(a==='inspect'){screen='mission';reviewing=true;s.step=3;workView='model';modelMode='tables';top=true;}
 if(a==='back'){if(i>0)pageByStep[s.step]=i-1;else if(s.step>0){s.step--;pageByStep[s.step]=Math.max(0,V3Session.items(c,s).length-1);}if(s.step<3)modelMode='er';card=true;}
 if(a==='next-card'){pageByStep[s.step]=i+1;card=true;}
 if(a==='export-html')download(reportHTML(),'Officina-ER-riepilogo.html','text/html');
 if(a==='solve-card'){
 const solved=ER.empty(c);ER.solve(c,solved,s.step);s.passed=s.passed.filter(n=>n<s.step);s.completed=false;
 if(!item)ER.solve(c,s,s.step);
 else if(s.step===1){s.attrs[item.id]=solved.attrs[item.id];s.keys[item.id]=solved.keys[item.id];s.identifications[item.id]=solved.identifications[item.id];}
 else if(s.step===2)s.relations[item.id]=solved.relations[item.id];
 else if(s.step===3){if(solved.tables[item.id])s.tables[item.id]=solved.tables[item.id];else delete s.tables[item.id];}
 else if(s.step===4)s.quiz[item.id]=solved.quiz[item.id];
 if(!s.assisted.includes(s.step))s.assisted.push(s.step);delete game.checks[current]?.[s.step];runFor().hints++;logEvent('soluzione',{item:item?.name||'passaggio'});card=true;
 }
 if(a==='verify-stage')finishStep(c,s);
 if(a==='advance'){if(s.step<4){s.step++;pageByStep={};modelMode=s.step===3?'tables':'er';card=true;}else{screen='boss';initBoss();top=true;}}
 if(a==='verify'){
  if(s.step===2&&!s.associationsConfirmed){const result=ER.checkAssociations(c,s);if(result.ok){s.associationsConfirmed=true;pageByStep={};card=true;}else localFeedback={ok:false,issues:['Rivedi le azioni presenti nella traccia: alcune mancano o non sono richieste.']};logEvent('verifica-associazioni',{ok:result.ok});}
  else if(item){const result=V3Session.checkItem(c,s,item.id,ER);if(result.ok){markChecked(s,item.id);localFeedback={ok:true,message:item.name+' verificata.'};if(list.every(it=>checked(s,it.id)))finishStep(c,s);}else localFeedback={ok:false,issues:V3Session.guidance(c,s,item.id,result,ER)};logEvent('verifica-scheda',{ok:result.ok,item:item.name,issues:result.issues});}
  else if(s.step===3){localFeedback={ok:false,issues:['Scegli le relazioni da creare, poi aggiungi le colonne.']};}
  else{const result=ER.check(c,s,s.step);if(result.ok)finishStep(c,s);else localFeedback={ok:false,issues:V3Session.guidance(c,s,null,result,ER)};logEvent('verifica',{ok:result.ok});}
 }
 save();persistGame();render();if(top)goTop();else if(card)focusCard();else {const f=document.getElementById('feedback');f?.focus({preventScroll:true});f?.scrollIntoView({block:'center',behavior:'instant'});}
}
document.addEventListener('click',actionV3);
// Intercept the legacy repair check before its handler to keep V3 scoring consistent.
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-game=\"boss-check\"]');if(!el)return;event.stopImmediatePropagation();
 const c=cases.find(c=>c.id===current),s=states[current],r=runFor(),result=ER.check(c,r.boss,3);let gain=0;
 if(result.ok){if(!r.rewarded.includes('boss')){r.rewarded.push('boss');r.points+=100;gain=100;}r.bossPassed=true;s.completed=true;game.best[current]={points:Math.max(game.best[current]?.points||0,r.points)};screen='complete';reviewing=false;notice='';}
 else notice='Il vincolo non rispetta ancora la traccia. Controlla quali righe devono poter coesistere e quali riferimenti devono esistere.';
 logEvent('collaudo-guasto',{ok:result.ok,gain,issues:result.issues});save();persistGame();render();goTop();
},true);
// Preserve disclosure state across the shared editor's re-renders.
document.addEventListener('click',e=>{const summary=e.target.closest('#task-brief > summary');if(summary)briefOpen[current]=!summary.parentElement.open;},true);
document.addEventListener('toggle',e=>{if(e.target.id==='task-brief'){const label=e.target.querySelector('summary span');if(label)label.textContent=e.target.open?'Riduci':'Leggi';}},true);
logEvent('apertura',{version:3});
render();
